import{_ as a,o as t,c as r,a5 as n}from"./chunks/framework.bIR-4glx.js";const m=JSON.parse('{"title":"Reading Map: Enter by Problem","description":"Seven doorways into Still Here, a table for choosing one English skill, one complete reading arc, and the four traces worth leaving from every chapter.","frontmatter":{"title":"Reading Map: Enter by Problem","description":"Seven doorways into Still Here, a table for choosing one English skill, one complete reading arc, and the four traces worth leaving from every chapter.","updated":"2026-11-23T00:00:00.000Z"},"headers":[],"relativePath":"en/reference/reading-map.md","filePath":"en/reference/reading-map.md","lastUpdated":1795392000000}'),o={name:"en/reference/reading-map.md"};function i(d,e,s,l,h,c){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="reading-map-enter-by-problem" tabindex="-1">Reading Map: Enter by Problem <a class="header-anchor" href="#reading-map-enter-by-problem" aria-label="Permalink to &quot;Reading Map: Enter by Problem&quot;">​</a></h1><p>This map answers one concrete question: <strong>what do I most need to see clearly, complete, or stop today?</strong> Find the cell closest to your situation, read one section, pause, do one small action, and then choose the next page.</p><h2 id="choose-today-s-entry-point" tabindex="-1">Choose Today&#39;s Entry Point <a class="header-anchor" href="#choose-today-s-entry-point" aria-label="Permalink to &quot;Choose Today&#39;s Entry Point&quot;">​</a></h2><h3 id="i-only-want-to-begin-again" tabindex="-1">I only want to begin again <a class="header-anchor" href="#i-only-want-to-begin-again" aria-label="Permalink to &quot;I only want to begin again&quot;">​</a></h3><p>Read the <a href="./../threads/part-0/prologue">Prologue: Do Not Rush to Change Your Life</a>, then open <a href="./../templates/learning-state">Learning State</a>. If you have five minutes, write only the real problem, the clues you already have, one minimum action, and the boundary you must keep. You do not need a three-year plan first.</p><h3 id="i-want-to-improve-one-concrete-english-skill" tabindex="-1">I want to improve one concrete English skill <a class="header-anchor" href="#i-want-to-improve-one-concrete-english-skill" aria-label="Permalink to &quot;I want to improve one concrete English skill&quot;">​</a></h3><p>Use <a href="./../threads/part-1/0-cefr">CEFR Goals and Self-check</a> to name the context and starting point, then choose one line below. Choose only one at a time, keep a first sample and the matching <a href="./glossary#tools-and-delivery">evidence card</a>, and do not let the wish to learn everything postpone the start.</p><table tabindex="0"><thead><tr><th>The barrier in front of you</th><th>Enter here</th><th>First trace to leave</th></tr></thead><tbody><tr><td>Too many unknown words and no sense of what to check</td><td><a href="./../threads/part-1/2-vocabulary">Vocabulary</a> · <a href="./../templates/vocabulary-audit">Vocabulary Evidence Card</a></td><td>A decision record and an unaided retrieval sample</td></tr><tr><td>The rules seem familiar, but expression changes time, responsibility, or certainty</td><td><a href="./../threads/part-1/grammar">Grammar</a> · <a href="./../templates/grammar-evidence">Grammar Evidence Card</a></td><td>A before-and-after sample using one high-impact structure</td></tr><tr><td>You collect audio but still need captions to understand</td><td><a href="./../threads/part-1/3-listening">Listening</a> · <a href="./../templates/listening-audit">Listening Evidence Card</a></td><td>A first pass, error map, and parallel transfer</td></tr><tr><td>Documentation is slow, and reading does not become delivery</td><td><a href="./../threads/part-1/4-reading">Reading</a> · <a href="./../templates/reading-evidence">Reading Evidence Card</a></td><td>A list of claims, evidence, and minimum technical facts</td></tr><tr><td>Fluency lives only inside a script, and follow-up questions end the exchange</td><td><a href="./../threads/part-1/5-speaking">Speaking</a> · <a href="./../templates/speaking-evidence">Speaking Evidence Card</a></td><td>A listener retelling, repair, or response to an unfamiliar question</td></tr><tr><td>You cannot leave your own draft and only have AI-polished prose</td><td><a href="./../threads/part-1/6-writing">Writing</a> · <a href="./../templates/writing-evidence">Writing Evidence Card</a></td><td>An unaided draft, its sources, and the reasons for revision</td></tr></tbody></table><p>More study is not necessarily deeper study. Ability begins to show when the action survives a new situation.</p><h3 id="i-am-preparing-for-a-global-role-or-remote-interview" tabindex="-1">I am preparing for a global role or remote interview <a class="header-anchor" href="#i-am-preparing-for-a-global-role-or-remote-interview" aria-label="Permalink to &quot;I am preparing for a global role or remote interview&quot;">​</a></h3><p>Read <a href="./../threads/part-1/8-job-search-english">Job-search English: Bring Ability into Interviews and Remote Work</a> before using one CEFR label to decide whether you are “good enough”. Choose one real role and use the <a href="./../templates/interview-evidence">Job-search English Evidence Card</a> for an unscripted project explanation, an unfamiliar follow-up, an asynchronous update, and a repair. Then decide whether to apply, repair one high-risk gap, or defer this role.</p><h3 id="i-have-many-resources-but-no-artifact" tabindex="-1">I have many resources but no artifact <a class="header-anchor" href="#i-have-many-resources-but-no-artifact" aria-label="Permalink to &quot;I have many resources but no artifact&quot;">​</a></h3><p>Read <a href="./../threads/part-3/1-ai-learning">Learning Anything with AI</a>, record the problem, sources, privacy boundary, and human judgment in the <a href="./../templates/ai-task-brief">AI Task Brief</a>, then use the <a href="./../templates/artifact-brief">Artifact Brief and Delivery Card</a> to name the audience, completion standard, acceptance owner, and rollback. A chat log can help you begin. It cannot deliver for you.</p><h3 id="i-have-many-records-but-cannot-tell-whether-i-really-changed" tabindex="-1">I have many records but cannot tell whether I really changed <a class="header-anchor" href="#i-have-many-records-but-cannot-tell-whether-i-really-changed" aria-label="Permalink to &quot;I have many records but cannot tell whether I really changed&quot;">​</a></h3><p>Open the <a href="./../templates/evidence-chain">Evidence Chain Template</a>. Put baseline, immediate performance, delayed retention, and transfer on one page, then return to <a href="./../threads/part-3/5-evidence-and-transfer">Evidence: How Change Becomes Visible</a> to separate supported conclusions from interpretations still waiting for a test. If you do not know which worksheet to choose, follow the <a href="./../templates/toolkit-walkthrough">Toolkit Walkthrough</a> once, then return to the <a href="./../templates/toolkit">Toolkit Overview</a> and choose by the obstacle in front of you.</p><h3 id="i-am-supporting-a-middle-school-age-learner" tabindex="-1">I am supporting a middle-school-age learner <a class="header-anchor" href="#i-am-supporting-a-middle-school-age-learner" aria-label="Permalink to &quot;I am supporting a middle-school-age learner&quot;">​</a></h3><p>Read <a href="./../threads/part-4/family-learning">Family Learning: Return Ownership to the Learner</a> before applying adult assumptions about time management, career projects, and AI accounts. Use the <a href="./../templates/family-learning-agreement">Family Learning Agreement</a> to record the learner&#39;s goals, the adult&#39;s worries, school requirements, data boundaries, and a review date. The learner speaks first; adults protect safety and environment without substituted work or all-day surveillance.</p><h3 id="i-am-in-a-difficult-season-and-my-capacity-is-small" tabindex="-1">I am in a difficult season and my capacity is small <a class="header-anchor" href="#i-am-in-a-difficult-season-and-my-capacity-is-small" aria-label="Permalink to &quot;I am in a difficult season and my capacity is small&quot;">​</a></h3><p>Read <a href="./../threads/part-2/recovery">Recovery: Catch Yourself Before You Push Forward</a> and <a href="./../threads/part-4/daily-system">Daily System</a>. Today&#39;s target may be safety, food, sleep, asking for help, and pausing. These are worthy of care on their own; you do not have to produce an impressive output to prove that you are still moving. If low mood, sleeplessness, hopelessness, or thoughts of harm persist, contact someone you trust and seek qualified local medical or mental-health support. This book is not care.</p><h2 id="one-complete-reading-arc" tabindex="-1">One Complete Reading Arc <a class="header-anchor" href="#one-complete-reading-arc" aria-label="Permalink to &quot;One Complete Reading Arc&quot;">​</a></h2><p>A complete read is not a race through page numbers. It lets the same question change several times: first see yourself, then return to life, learn again, amplify ability with tools, and finally give the rhythm to time.</p><table tabindex="0"><thead><tr><th>Stage</th><th>What to read</th><th>What to leave behind</th></tr></thead><tbody><tr><td>See the starting point</td><td><a href="./../threads/part-0/prologue">Prologue</a> · <a href="./../threads/part-2/my-story">My Story</a></td><td>A one-page promise: real problem, baseline, minimum action, and boundary</td></tr><tr><td>Return to life</td><td><a href="./../threads/part-2/recovery">Recovery</a> · <a href="./../threads/part-2/decision">Decision-Making</a> · <a href="./../threads/part-2/relationships">Relationships</a></td><td>Three confirmable facts, one responsibility to carry, and one boundary</td></tr><tr><td>Learn again</td><td><a href="./../threads/part-1/0-cefr">CEFR Self-check</a> and the vocabulary, grammar, listening, reading, speaking, and writing chapters</td><td>An <a href="./../templates/english-diagnostic">English Diagnostic</a> and one matching <a href="./glossary#tools-and-delivery">evidence card</a></td></tr><tr><td>Amplify ability</td><td><a href="./../threads/part-3/1-ai-learning">Learning Anything with AI</a> · <a href="./../threads/part-3/4-artifacts-and-delivery">Artifacts</a> · <a href="./../threads/part-3/5-evidence-and-transfer">Evidence</a></td><td>One inspectable small experiment and one real delivery</td></tr><tr><td>Practice and deliver</td><td><a href="./../threads/part-4/week-1">First Week Practice</a> · <a href="./../threads/part-5/90-day-plan">90-Day Action Plan</a> · <a href="./../threads/part-6/1-understanding-yourself">Be Your Own Lifelong Friend</a></td><td>A first-week baseline, one <a href="./../templates/rhythm-ledger">Rhythm Ledger</a>, one real-project handover, and the next review date</td></tr></tbody></table><h2 id="leave-four-traces-from-every-chapter" tabindex="-1">Leave Four Traces from Every Chapter <a class="header-anchor" href="#leave-four-traces-from-every-chapter" aria-label="Permalink to &quot;Leave Four Traces from Every Chapter&quot;">​</a></h2><p>After a chapter, do not mark only “read”. Leave at least two of these four traces:</p><table tabindex="0"><thead><tr><th>Trace</th><th>Question</th><th>Example</th></tr></thead><tbody><tr><td>One judgment</td><td>What am I more certain about now?</td><td>“I will track one main question this week.”</td></tr><tr><td>One sample</td><td>What output proves I did the work?</td><td>A recording, an email, or an error list</td></tr><tr><td>One boundary</td><td>What must not be handed to a tool or an assumption?</td><td>Do not upload customer privacy; do not turn one story into a rule</td></tr><tr><td>One return point</td><td>When and under what condition will I retest?</td><td>Repeat the task with a new topic in seven days</td></tr></tbody></table><p>If a chapter leaves only “that makes sense”, stop collecting. Rewrite it as an action that another person could see and you could inspect later.</p><h2 id="back-to-the-reader-s-guide" tabindex="-1">Back to the Reader&#39;s Guide <a class="header-anchor" href="#back-to-the-reader-s-guide" aria-label="Permalink to &quot;Back to the Reader&#39;s Guide&quot;">​</a></h2><p>This map only points at entry doors. For how to arrange a complete read, how to return after an interruption, and what the book will not do for you, see <a href="./../threads/part-0/reader-guide">How to Read This Book</a>. If you want to do one thing today, open <a href="./../templates/learning-state">Learning State</a> and write the problem, the clues, the minimum action, and the boundary.</p>',28)])])}const u=a(o,[["render",i]]);export{m as __pageData,u as default};
